  choices = $EXPL$["No, because Parker is not related to Gomez by blood, marriage, or adoption","Yes, because an unrelated household member for the full year satisfies the relationship test","No, because qualifying relative rules require a formal legal guardianship arrangement","Yes, but only if Parker is a minor dependent who is under the age of 18"]$EXPL$::jsonb,
