  choices = $EXPL$["Any qualifying relative who is a dependent of the taxpayer","A dependent child such as a son, daughter, or stepchild of the taxpayer","The deceased spouse''s parent who qualifies as a dependent","Any person who is related by blood or marriage to the deceased spouse"]$EXPL$::jsonb,
